// ============================================================================
// GROWTH DIRECTOR — DETERMINISTIC PRIORITIZATION (no LLM, no fabricated data)
// ============================================================================
// Every open task receives a decision score assembled ONLY from data that
// exists on the task row. Missing optional data contributes a documented
// neutral weight — never an invented value.
//
// score =
//   priority_base      P0=40  P1=30  P2=20  P3=10            (always present)
//   + confidence       round(confidence * 15); missing -> 7.5 (neutral midpoint)
//   + impact_boost     keyword scan of expected_impact / payload.expected_impact:
//                        revenue, pipeline, booked, lead, conversion, clicks -> +15
//                        ranking, traffic, seo, citation -> +8
//                        otherwise 0
//   + intent_boost     +10 when the task itself signals buying intent
//                        (task_type 'lead_intent_hot' or payload.intent_score)
//   + freshness_boost  created <24h -> +10, <72h -> +5, older -> 0
//   + approval_boost   +5 when requires_approval (a human decision is the
//                      bottleneck; surfacing it early unblocks revenue work)
//   + effort_adjust    payload.effort: 'small'/'low' -> +5, 'large'/'high' -> -10,
//                      missing -> 0
//
// Ties break by created_at (newest first), then by title for determinism.
// ============================================================================
const tasks = $('Gather Open Tasks').all().map(i => i.json).filter(t => t && t.id);
const agents = $('Gather Agent Health').all().map(i => i.json).filter(a => a && a.slug);
const runs = items.map(i => i.json).filter(r => r && r.status);

const PRIORITY_BASE = { P0: 40, P1: 30, P2: 20, P3: 10 };
const HIGH_IMPACT = /(revenue|pipeline|booked|lead|conversion|clicks)/i;
const MED_IMPACT = /(ranking|traffic|seo|citation)/i;

function domainOf(taskType) {
  if (/^seo_/.test(taskType)) return 'SEO Intelligence';
  if (/^(search_opportunity|content_research)/.test(taskType)) return 'Search Opportunity / Research';
  if (/^internal_/.test(taskType)) return 'Internal Linking';
  if (/^technical_seo/.test(taskType)) return 'Technical SEO';
  if (/^citation/.test(taskType)) return 'Citation Engine';
  if (/^backlink/.test(taskType)) return 'Backlink Intelligence';
  if (/^review_founder/.test(taskType)) return 'Founder Content';
  if (/^review_social/.test(taskType)) return 'Social Distribution';
  if (/^cro_/.test(taskType)) return 'CRO Intelligence';
  if (/^competitor/.test(taskType)) return 'Competitor Intelligence';
  if (/^reputation/.test(taskType)) return 'Reputation Intelligence';
  if (/^lead_intent/.test(taskType)) return 'Lead Intent';
  if (/^publishing_stuck/.test(taskType)) return 'Publisher';
  return 'GrowthOS';
}

function factorsOf(t, parts) {
  const f = [];
  if (parts.priority_base >= 30) f.push(parts.priority_base >= 40 ? 'critical priority' : 'high priority');
  if (parts.impact_boost >= 15) f.push('revenue-linked impact');
  else if (parts.impact_boost > 0) f.push('growth impact');
  if (parts.intent_boost > 0) f.push('explicit buying intent');
  if (parts.freshness_boost > 0) f.push('fresh finding');
  if (t.requires_approval) f.push('waiting on your approval');
  return f;
}

const scored = tasks.map(t => {
  const payload = (t.payload && typeof t.payload === 'object') ? t.payload : {};
  const impactText = [t.expected_impact, payload.expected_impact].filter(Boolean).join(' ');
  const priority_base = PRIORITY_BASE[t.priority] !== undefined ? PRIORITY_BASE[t.priority] : 10;
  const confidence = (typeof t.confidence === 'number' && t.confidence >= 0 && t.confidence <= 1) ? t.confidence : null;
  const confidencePts = confidence === null ? 7.5 : Math.round(confidence * 15 * 10) / 10;
  const impact_boost = HIGH_IMPACT.test(impactText) ? 15 : (MED_IMPACT.test(impactText) ? 8 : 0);
  const intent_boost = (t.task_type === 'lead_intent_hot' || payload.intent_score !== undefined) ? 10 : 0;
  const ageH = (Date.now() - new Date(t.created_at).getTime()) / 3600000;
  const freshness_boost = ageH < 24 ? 10 : (ageH < 72 ? 5 : 0);
  const approval_boost = t.requires_approval ? 5 : 0;
  const effort = String(payload.effort || '').toLowerCase();
  const effort_adjust = effort === 'small' || effort === 'low' ? 5 : (effort === 'large' || effort === 'high' ? -10 : 0);
  const score = priority_base + confidencePts + impact_boost + intent_boost + freshness_boost + approval_boost + effort_adjust;
  const parts = { priority_base, confidencePts, impact_boost, intent_boost, freshness_boost, approval_boost, effort_adjust };
  return {
    id: t.id, task_type: t.task_type, title: t.title, priority: t.priority,
    requires_approval: !!t.requires_approval, domain: domainOf(t.task_type || ''),
    action: (t.description || t.title || '').slice(0, 180),
    score: Math.round(score * 10) / 10, parts,
    why: factorsOf(t, parts).join(', ') || 'routine finding',
    created_at: t.created_at
  };
});

scored.sort((a, b) => b.score - a.score || new Date(b.created_at) - new Date(a.created_at) || (a.title < b.title ? -1 : 1));
const top = scored.slice(0, 5);

const byPrio = { P0: 0, P1: 0, P2: 0, P3: 0 };
tasks.forEach(t => { byPrio[t.priority] = (byPrio[t.priority] || 0) + 1; });
const failedRuns = runs.filter(r => r.status === 'failed' || r.error).length;
const completedRuns = runs.filter(r => r.status === 'completed').length;
const tasksCreated = runs.reduce((s, r) => s + (r.tasks_created || 0), 0);
const hourBudget = (a) => a.schedule === 'hourly' ? 6 : a.schedule === 'daily' ? 36 : 180;
const stale = agents.filter(a => a.status === 'active' && a.schedule && a.schedule !== 'on-demand' && (!a.last_run_at || (Date.now() - new Date(a.last_run_at).getTime()) / 3600000 > hourBudget(a)));

const lines = [];
lines.push('GrowthOS daily brief — ' + new Date().toISOString().slice(0, 10));
lines.push('');
lines.push('TOP ACTIONS TODAY');
top.forEach((t, i) => {
  lines.push((i + 1) + '. [' + t.priority + (t.requires_approval ? '·approval' : '') + '] ' + t.title.slice(0, 90));
  lines.push('   Why: ' + t.why + ' | Found by: ' + t.domain + ' | Score ' + t.score);
});
if (!top.length) lines.push('No open tasks — nothing needs a decision.');
lines.push('');
lines.push('SYSTEM HEALTH');
lines.push('Runs last 24h: ' + completedRuns + ' completed, ' + failedRuns + ' failed | tasks created: ' + tasksCreated);
lines.push('Open tasks: ' + tasks.length + ' (P0: ' + byPrio.P0 + ', P1: ' + byPrio.P1 + ', P2: ' + byPrio.P2 + ', P3: ' + byPrio.P3 + ')' + (stale.length ? ' | UNHEALTHY/STALE: ' + stale.map(a => a.slug).join(', ') : ' | all agents on schedule'));

const brief = {
  brief_date: new Date().toISOString().slice(0, 10),
  executive_summary: lines.join('\n'),
  priorities: top.map(t => ({ title: t.title, domain: t.domain, score: t.score, requires_approval: t.requires_approval, why: t.why, action: t.action })),
  metrics: { open_tasks: tasks.length, by_priority: byPrio, runs_24h: { completed: completedRuns, failed: failedRuns }, tasks_created_24h: tasksCreated, stale_agents: stale.map(a => a.slug), scored_tasks: scored.length }
};
return [{ json: { brief, telegram_message: lines.join('\n'), summary: { open_tasks: tasks.length, top_recommendations: top.length, runs_24h_completed: completedRuns, runs_24h_failed: failedRuns, stale_agents: stale.length }, tasks_created: 0 } }];
